import json
from pathlib import Path
path = Path('logs/trading_log_tower.ndjson')
if not path.exists():
    print('missing')
    raise SystemExit
with path.open('r', encoding='utf-8') as f:
    for i, line in enumerate(f, 1):
        try:
            obj = json.loads(line)
        except json.JSONDecodeError:
            continue
        p9 = obj.get('P9') or {}
        if isinstance(p9, dict) and 'action' in p9 and p9['action'] is not None:
            print('line', i, 'action', p9['action'])
            break
        if i > 5000:
            print('no action in first 5000 lines')
